// Metadata-only: never include ciphertext in queue/oversight lists.
// Authorization/eligible reviewer filtering remains the service's responsibility.
func (q *Queries) ListApprovalRequests(ctx context.Context, arg ListApprovalRequestsParams) ([]ListApprovalRequestsRow, error) {
	rows, err := q.db.Query(ctx, listApprovalRequests,
		arg.RequesterKind,
		arg.RequesterID,
		arg.Status,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListApprovalRequestsRow{}
	for rows.Next() {
		var i ListApprovalRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.RuleID,
			&i.RuleRevision,
			&i.ContextEpoch,
			&i.RequesterKind,
			&i.RequesterID,
			&i.RequesterTeamID,
			&i.GatewayID,
			&i.ServerID,
			&i.CapabilityID,
			&i.ExposedName,
			&i.ToolClass,
			&i.ArgsDigest,
			&i.BindingDigest,
			&i.CapabilityFingerprint,
			&i.ServerOrigin,
			&i.PreviewTruncated,
			&i.PreviewRedacted,
			&i.Status,
			&i.ReviewRevision,
			&i.DecidedBy,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.ValidUntil,
			&i.DecidedAt,
			&i.UsedAt,
			&i.TerminalAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

