const purgeApprovalRequestMetadata = `-- name: PurgeApprovalRequestMetadata :execrows
WITH doomed AS (
    SELECT id FROM approval_requests WHERE terminal_at < $1::timestamptz - interval '2160 hours'
    ORDER BY terminal_at, id LIMIT $2::integer FOR UPDATE SKIP LOCKED
)
DELETE FROM approval_requests WHERE id IN (SELECT id FROM doomed)
`

type PurgeApprovalRequestMetadataParams struct {
	AtTime    time.Time
	BatchSize int32
}

// Independent 90-day metadata retention, never audit's retention setting.
func (q *Queries) PurgeApprovalRequestMetadata(ctx context.Context, arg PurgeApprovalRequestMetadataParams) (int64, error) {
	result, err := q.db.Exec(ctx, purgeApprovalRequestMetadata, arg.AtTime, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

